// Builds public/icons.svg, a small sprite of the Lucide icons the UI uses.
// lucide-static is a dev dependency (~60 MB), so only this generated file ships.
// Run after changing the list: npm run icons

import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ICONS = [
  'plus', 'panel-left', 'trash-2', 'download', 'rotate-cw', 'square', 'arrow-up',
  'sun', 'moon', 'refresh-cw', 'circle-alert', 'message-square',
  'file-code', 'rocket', 'external-link', 'circle-check', 'circle-x', 'loader-circle', 'globe', 'minus',
];

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const src = path.join(root, 'node_modules', 'lucide-static', 'icons');
const { version } = JSON.parse(readFileSync(path.join(root, 'node_modules', 'lucide-static', 'package.json'), 'utf8'));

const symbols = ICONS.map((name) => {
  const svg = readFileSync(path.join(src, `${name}.svg`), 'utf8');
  const inner = svg.replace(/<!--[\s\S]*?-->/g, '').replace(/^[\s\S]*?<svg[^>]*>/, '').replace(/<\/svg>\s*$/, '').trim();
  return `  <symbol id="${name}" viewBox="0 0 24 24">${inner.replace(/\s*\n\s*/g, '')}</symbol>`;
});

const out = [
  `<!-- Lucide icons v${version} (https://lucide.dev), ISC License. Generated by scripts/build-icons.js -->`,
  '<svg xmlns="http://www.w3.org/2000/svg">',
  ...symbols,
  '</svg>',
  '',
].join('\n');

writeFileSync(path.join(root, 'public', 'icons.svg'), out);
console.log(`Wrote public/icons.svg (${ICONS.length} icons, Lucide ${version})`);
